DROP TABLE "games" CASCADE;
DROP TABLE "achivements" CASCADE;
DROP TABLE "game_art" CASCADE;
DROP TABLE "developer_studio" CASCADE;
DROP TABLE "publisher" CASCADE;

CREATE TABLE IF NOT EXISTS "games" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"studio_id" INTEGER NOT NULL,
	"publisher_id" INTEGER,
	"name" TEXT NOT NULL,
	"description" TEXT NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "achivements" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"game_id" INTEGER NOT NULL,
	"icon" TEXT,
	"description" TEXT,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "game_art" (
	"game_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"header" TEXT,
	"icon" TEXT,
	"capsule" TEXT,
	PRIMARY KEY("game_id")
);

CREATE TABLE IF NOT EXISTS "developer_studio" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" TEXT NOT NULL,
	"description" TEXT NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "publisher" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" TEXT NOT NULL,
	"description" TEXT NOT NULL,
	PRIMARY KEY("id")
);

ALTER TABLE "achivements"
ADD FOREIGN KEY("game_id") REFERENCES "games"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "game_art"
ADD FOREIGN KEY("game_id") REFERENCES "games"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "games"
ADD FOREIGN KEY("studio_id") REFERENCES "developer_studio"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "games"
ADD FOREIGN KEY("publisher_id") REFERENCES "publisher"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
